@startuml

class Hospital {}

abstract class Department {}

class EmergencyRoom extends Department {}

abstract class StaffedDepartment extends Department {}

class InternalMedicine extends StaffedDepartment {}

class Surgery extends StaffedDepartment {}

class Obstetrics extends StaffedDepartment {}

class Shift {
  + date : date
}

class MedicalStaff {
  + name : string
  + qualification : string
}

class AdministrativeStaff {
  + name : string
  + seniority : int
}

class Staff {}

class Patient {
  + name : string
  + taxCode : string
  + dateOfBirth : date
}

class Admission {
  + checkIn : date
  + checkOut : date
}

class AdmissionHistory {}

class MedicalRecord {}

Hospital "1" o-- "1..*" AdministrativeStaff
Hospital "1" *-- "1..*" Department
EmergencyRoom "1" -- "1..*" Shift
Shift "0..*" -- "1..*" MedicalStaff
StaffedDepartment "1" o-- "1..*" MedicalStaff
Patient "1" -- "1..*" Admission
Admission "1" -- "1" AdmissionHistory
MedicalRecord "1" *-- "1..*" AdmissionHistory
Patient "1" -- "1" MedicalRecord
Department "1" -- "0..*" Shift
Department "1" -- "1..*" MedicalStaff
Department "1" -- "*" Patient

@enduml

